BASE=Path(__file__).resolve().parents[1];T=BASE/'tables';FIG=BASE/'figures';COL={'FLT':'#0072B2','GC':'#D55E00','VIV':'#7356A8'}

def sha(path):
    h=hashlib.sha256()
    with open(path,'rb') as f:
        for b in iter(lambda:f.read(1048576),b''):h.update(b)
    return h.hexdigest()

def md(frame):
    out=['| '+' | '.join(map(str,frame.columns))+' |','| '+' | '.join(['---']*len(frame.columns))+' |']
    for vals in frame.itertuples(index=False,name=None):out.append('| '+' | '.join(str(v).replace('|','/') for v in vals)+' |')
    return '\n'.join(out)

def main():
    FIG.mkdir(exist_ok=True);s=json.loads((T/'summary.json').read_text());v=json.loads((T/'independent_verification.json').read_text());prov=json.loads((BASE/'inputs/provenance.json').read_text());members=pd.read_csv(T/'Tcaf1_measured_junction_transcripts.csv');tx=pd.read_csv(T/'Tcaf1_transcript_CDS_UTR_summary.csv');animal=pd.read_csv(T/'Tcaf1_all26_long_short_intron_support.csv');group=pd.read_csv(T/'Tcaf1_group_read_support_summary.csv');intron=pd.read_csv(T/'Tcaf1_all_annotated_intron_read_counts.csv.gz');unnamed=pd.read_csv(T/'unnamed_gene_identity_audit.csv');rel=pd.read_csv(T/'Tcaf1_descriptive_fraction_coverage_relation.csv')
