    fig,axs=plt.subplots(2,2,figsize=(183/25.4,155/25.4));fig.subplots_adjust(left=.15,right=.965,bottom=.16,top=.94,wspace=.45,hspace=.64)
    ax=axs[0,0];names=['Tcaf1-201','Tcaf1-202','Tcaf1-203','Tcaf1-205','Tcaf1-206','Tcaf1-208'];ys=np.arange(6)
    for y,name in zip(ys,names):
        r=core[core.transcript_name==name].iloc[0];kb=r.intron_length_bp/1000;coding=name in names[:3];ax.plot([0,kb],[y,y],c='#405765' if coding else '#888888',lw=1,ls='-' if coding else '--');ax.plot(kb,y,'o',c='#405765' if coding else '#888888',ms=3,markerfacecolor='#405765' if coding else 'white',markeredgewidth=1);ax.text(24.2,y,f'{r.donor_exon_rank}→{r.acceptor_exon_rank}',va='center',fontsize=8)
    ax.set_yticks(ys,names);ax.invert_yaxis();ax.set_xlim(-.3,29);ax.set_ylim(5.5,-.75);ax.set_xticks([0,6,12,18,24]);ax.set_xlabel('Matched intron span (kb)');ax.set_title('a) Exact reference memberships',loc='left',fontweight='bold');ax.text(.01,-.34,'Filled: 5′ UTR boundaries in coding transcripts\nRight labels: donor→acceptor exon ranks',transform=ax.transAxes,fontsize=8)
