    ax.set_xticks(range(3),COL);ax.set_ylabel('Companion junction unique reads');ax.set_title('d) Additional local junction support',loc='left',fontweight='bold');ax.set_ylim(0,185);ax.set_xlabel('Same 26 animals; segments are means')
    fig.text(.15,.042,'Exact GTF matches: 2,049/3,248 multiway junctions; 1,199 unmatched remain in the audit.\nReference membership and same-library read support do not identify complete transcripts or protein effects.',fontsize=8)
    fig.canvas.draw();renderer=fig.canvas.get_renderer();fw,fh=fig.canvas.get_width_height();text_objects=[o for o in fig.findobj(matplotlib.text.Text) if o.get_visible() and o.get_text().strip()]
